// language.js — grounded language cortex
//
// No LLM. No templates. No pretrained grammar.
//
// Speech is generated by:
//   1. Recalling utterance memories (things heard or said before)
//   2. Mutating them toward the current concept/emotional state
//   3. Falling back to minimal primitives only when no utterances exist yet
//
// This means the system's speech patterns are entirely learned from experience.
// It speaks the way it has heard things spoken, shaped by what it currently feels.
// The more it hears, the richer its speech becomes.
// Patterns that produce positive outcomes (dopamine) get reinforced in memory.js.

// ── understand ────────────────────────────────────────────────────────────────
// Intent classification driven entirely by what the brain has learned.
// Recalls utterance memories that match the input, reads back their intent tag.
// No hardcoded regexes — the boot curriculum is the parser.

const SKIP_WORDS = new Set([
    'what','who','where','when','why','how','is','are','am','was','were','be','been','being',
    'that','this','with','from','just','like','about','have','your','they','them','their',
    'here','there','will','would','could','should','does','dont','cant','wont','hello','name',
    'the','a','an','very','much','more','some','such','into','onto','over','under','after',
    'before','also','then','than','these','those','which','while','has','had','do','can',
    // Common adverbs/verbs that are never meaningful research topics
    'always','never','sometimes','often','still','again','already','really','actually',
    'understand','remember','think','feel','know','want','need','said','tell','says',
    'something','anything','nothing','everything','someone','anyone','everyone',
    'because','therefore','however','although','whether','through','between','during',
]);

function _selectEntities(text, context = {}) {
    const words = text.toLowerCase().replace(/[^a-z\s]/g, ' ').split(/\s+/).filter(Boolean);
    const contentWords = words.filter(w => w.length > 3 && !SKIP_WORDS.has(w));
    const contextTerms = (context.recentTopics || context.knowledge || [])
        .filter(Boolean).map(t => String(t).toLowerCase());

    // Resolve bare pronouns to current context subject
    if (contentWords.length === 1 && /^(it|that|this|they|them)$/.test(contentWords[0]) && contextTerms.length > 0)
        return contextTerms.slice(0, 5);
    if (contentWords.length === 0 && contextTerms.length > 0)
        return contextTerms.slice(0, 5);

    const contextAligned = contentWords.filter(w => contextTerms.some(t => t.includes(w) || w.includes(t)));
    const fallback = contextAligned.length > 0 ? contextAligned : contentWords;
    if (fallback.length === 0 && contextTerms.length > 0) return contextTerms.slice(0, 5);
    if (fallback.length === 1 && fallback[0] === 'it' && contextTerms.length > 0) return contextTerms.slice(0, 5);
    return [...new Set(fallback)].slice(0, 5);
}

export function understand(humanText, context = {}) {
    const lower = humanText.toLowerCase();
    const entities = _selectEntities(lower, context);

    // ── Intent from brain recall ──────────────────────────────────────────
    // Score each intent by how many recalled utterances for that intent
    // overlap with the input tokens. The intent whose training patterns
    // best match the input wins — no hardcoded rules.
    const intentScores = {};
    const cortex = context.cortex;
    if (cortex && typeof cortex.recall === 'function') {
        const inputTokens = new Set(lower.replace(/[^a-z\s]/g, ' ').split(/\s+/).filter(w => w.length > 2));
        const candidates = cortex.recall([...inputTokens].slice(0, 6), 'neutral', 20, 'understand');
        for (const mem of candidates) {
            const tag = mem.entities?.find(e => !e.startsWith('__') && !SKIP_WORDS.has(e) && e.length > 2
                && ['greeting','identity','correction','command','question','wellbeing','introspect',
                    'affirm','emotion','teaching','statement','farewell','social','answer','desire',
                    'knowledge','perception','action','description','temporal','hedge',
                    'response','human_speech'].includes(e));
            if (!tag) continue;
            const memTokens = new Set(mem.content.toLowerCase().replace(/[^a-z\s]/g, ' ').split(/\s+/).filter(w => w.length > 2));
            let overlap = 0;
            for (const t of inputTokens) if (memTokens.has(t)) overlap++;
            intentScores[tag] = (intentScores[tag] || 0) + overlap * mem.salience;
        }
    }

    // Pick highest-scoring intent, fall back to 'statement'
    let intent = 'statement';
    let bestScore = 0;
    for (const [tag, score] of Object.entries(intentScores)) {
        if (score > bestScore) { bestScore = score; intent = tag; }
    }

    // ── Topic: highest-salience entity not in skip list ───────────────────
    const topic = entities[0] || null;

    // ── Emotion: derived from concept activations in context ──────────────
    const negWords = ['hurt','pain','sad','angry','scared','afraid','alone','lost','wrong','bad','hate','fear'];
    const posWords = ['good','happy','love','safe','warm','friend','play','learn','know','trust','joy'];
    const hasNeg = negWords.some(w => lower.includes(w));
    const hasPos = posWords.some(w => lower.includes(w));
    const emotion = hasNeg ? 'upset' : hasPos ? 'happy' : 'neutral';

    return {
        intent,
        topic,
        entities,
        sentiment: hasNeg ? 'negative' : hasPos ? 'positive' : 'neutral',
        emotion,
        summary:   humanText,
        needsSearch: false,
        searchQuery: null,
    };
}

// ── Speech generation core ────────────────────────────────────────────────────
//
// _recallUtterances: pull speech pattern memories relevant to current context
// _mutate:           swap content words toward active concepts
// _primitive:        last-resort minimal output when memory is empty

// Track recently produced outputs and recently-used content words to avoid repetition
const _recentOutputs = [];
const _recentWords   = [];
const RECENT_CAP     = 12;
const RECENT_WORD_CAP = 30;

// Jaccard similarity between two token sets — used for detecting
// near-duplicate utterances (mutations of the same template).
function _tokenSet(text) {
    return new Set((text || '').toLowerCase().replace(/[^a-z\s]/g, ' ').split(/\s+/).filter(Boolean));
}
function _jaccard(a, b) {
    if (a.size === 0 && b.size === 0) return 1;
    let intersection = 0;
    for (const tok of a) if (b.has(tok)) intersection++;
    const union = a.size + b.size - intersection;
    return union === 0 ? 1 : intersection / union;
}

// Score an utterance by how many of its words overlap with the target entities.
// Higher overlap = more contextually relevant to the current topic.
function _relevanceScore(content, entities) {
    if (!entities || entities.length === 0) return 0;
    const words = content.toLowerCase().replace(/[^a-z\s]/g, ' ').split(/\s+/);
    return entities.reduce((n, e) => n + (words.some(w => w === e || w.startsWith(e) || e.startsWith(w)) ? 1 : 0), 0);
}

// Patterns that are high-salience from boot but become attractor loops in
// conversation — penalise them heavily during recall so they don't dominate.
// These are also filtered out entirely from conversational replies (respond())
// since they are aversion reflexes, not language.
const ATTRACTOR_PATTERNS = [
    /^danger reminds me of/i,
    /^pain reminds me of/i,
    /^(that hurts|i feel pain|stop that|danger here|this feels bad|this is too much|i need to get away from this|i want this to stop|i do not like this)$/i,
];

function _recallUtterances(cortex, entities, emotion, topN = 12, intentTag = null) {
    if (!cortex) return [];
    let all = cortex.recall(entities, emotion, topN * 2, 'speech')
        .filter(m => m.type === 'utterance')
        // Hard-filter aversion reflexes by both regex and intent tag
        .filter(m => !ATTRACTOR_PATTERNS.some(p => p.test(m.content)))
        .filter(m => !m.entities?.includes('aversion'));

    // When an intentTag is provided, prefer utterances whose entities include it.
    // This ensures greeting recall returns greeting phrases, not social phrases.
    if (intentTag) {
        const tagged = all.filter(m => m.entities.includes(intentTag));
        if (tagged.length >= 3) all = tagged;
    }

    // Sort by contextual relevance (entity overlap) descending, break ties randomly.
    return all
        .map(m => ({
            m,
            score: _relevanceScore(m.content, entities) + Math.random() * 0.4,
        }))
        .sort((a, b) => b.score - a.score)
        .slice(0, topN)
        .map(x => x.m);
}

const FUNC = new Set(['i','me','my','you','your','it','is','are','was','the','a','an',
    'and','or','but','in','on','at','to','of','for','not','do','did','have','has',
    'that','this','with','from','just','like','about','feel','feels','felt',
    'want','wants','wanted','know','knows','knew','think','thinks','thought',
    'see','sees','saw','get','gets','got','go','goes','went','come','came',
    'make','made','take','took','need','needs','needed','keep','kept',
    'here','there','something','anything','nothing','everything',
    // Question words and auxiliaries — _mutate must never corrupt grammatical structure
    'how','what','who','where','when','why','which','whose','whom',
    'does','can','could','would','should','will','shall','may','might','must',
    'am','be','been','being','had','were','do',
    // Words that appear as structural slots in fixed boot phrases — never swap these
    'worth','thinking','paying','attention','resonates','interesting','hello','goodbye',
    'welcome','sorry','please','thanks','okay','right','sure','agree','disagree',
    'point','sense','mean','means','said','says','told','tell','told',
    'understand','appreciate','saying','thought','talk','more','same','hear',
    'help','try','good','way','now','thank','want','said','glad','meet','care',
    'listen','listening','again','soon','later','back','next','last','first',
    'always','never','every','each','both','few','many','most','some','any',
    'place','time','life','world','mind','body','self','part','kind','type',
    'true','false','real','wrong','right','left','long','short','high','low',
    'say','makes','going','getting','putting','taking','giving','coming']);

// Softmax-sample from an array of concepts weighted by activation.
// Temperature < 1 sharpens the distribution; > 1 flattens it.
// Prevents the highest-activation node from winning every slot (argmax collapse).
function _softmaxSample(eligible, temperature = 0.8) {
    if (eligible.length === 0) return null;
    if (eligible.length === 1) return eligible[0];
    const weights = eligible.map(c => Math.exp(c.activation / temperature));
    const total   = weights.reduce((s, w) => s + w, 0);
    let r = Math.random() * total;
    for (let i = 0; i < eligible.length; i++) {
        r -= weights[i];
        if (r <= 0) return eligible[i];
    }
    return eligible[eligible.length - 1];
}

// Replace the single most relevant content word in a recalled utterance
// with a sampled active concept that isn't already present.
// Fixed phrases (tagged __fixed__ during boot) are returned unchanged.
// Preserves the grammatical skeleton — only the subject matter shifts.
// CONSERVATIVE: only swaps if it's safe (candidate is short, not a proper noun).
function _mutate(utterance, concepts, entities, isFixed = false) {
    if (isFixed || !utterance || concepts.length === 0) return utterance;

    // Strip punctuation for presence check so "good." doesn't block swapping "good"
    const uWords = new Set(
        utterance.toLowerCase().replace(/[^a-z\s]/g, ' ').split(/\s+/).filter(Boolean)
    );

    // Build eligible pool: not a stopword, not already in utterance.
    // IMPORTANT: Also filter out proper nouns (capitalized, or all-caps concept labels).
    // This prevents swapping "creator" or "Damian" into structural slots.
    const eligible = concepts.filter(c => {
        const lbl = c.label.toLowerCase();
        // Don't swap if: it's in FUNC, it's too short, it's already there,
        // it's been used recently, OR it looks like a proper noun (mostly capital letters)
        const isProperNoun = /[A-Z]/.test(c.label) && c.label.length < 10;
        return !FUNC.has(lbl) && lbl.length > 2 && lbl.length < 12 && !uWords.has(lbl) && 
               !_recentWords.includes(lbl) && !isProperNoun;
    });
    const fallback = eligible.length === 0
        ? concepts.filter(c => { 
            const lbl = c.label.toLowerCase(); 
            const isProperNoun = /[A-Z]/.test(c.label) && c.label.length < 10;
            return !FUNC.has(lbl) && lbl.length > 2 && lbl.length < 12 && !uWords.has(lbl) && !isProperNoun; 
          })
        : null;

    // Softmax-sample instead of argmax
    const candidate = _softmaxSample(eligible.length > 0 ? eligible : (fallback || []));
    if (!candidate) return utterance;

    const words = utterance.split(/\s+/);

    // Find the best slot to swap. Prefer stale words (not in current entities),
    // but also check that the word we're replacing is roughly the same length as
    // the candidate — long replacements tend to break sentence flow.
    let bestIdx = -1;
    let bestScore = -1;
    for (let i = 0; i < words.length; i++) {
        const w = words[i].toLowerCase().replace(/[^a-z]/g, '');
        if (FUNC.has(w) || w.length < 3) continue;
        // Avoid replacing very long words (likely structural) or very short words
        if (w.length > 15) continue;
        const isStale = !entities.some(e => w.includes(e) || e.includes(w));
        const score = isStale ? 1 : 0.2;
        if (score > bestScore) { bestScore = score; bestIdx = i; }
    }

    if (bestIdx === -1) return utterance;
    const result = [...words];
    // Preserve trailing punctuation from the replaced word
    const punct = words[bestIdx].match(/[.!?,]$/);
    result[bestIdx] = candidate.label + (punct ? punct[0] : '');
    return result.join(' ');
}

// Pick a non-recently-used utterance from the recalled set, mutate it.
// Falls back to least-recently-used if all have been seen recently.
// Uses Jaccard similarity to detect near-duplicates, not just exact matches.
function _pickAndMutate(utterances, concepts, entities) {
    if (utterances.length === 0) return null;
    
    // Prefer utterances that aren't similar to recent outputs (Jaccard > 0.65 = too similar)
    const fresh = utterances.filter(u => {
        const uTokens = _tokenSet(u.content);
        return !_recentOutputs.some(recent => _jaccard(uTokens, _tokenSet(recent)) > 0.65);
    });
    const pool  = fresh.length > 0 ? fresh : utterances;
    
    // Pick from the top-3 most relevant rather than purely random
    const picked = pool[Math.floor(Math.random() * Math.min(3, pool.length))];
    const isFixed = Array.isArray(picked.entities) && picked.entities.includes('__fixed__');
    const result = _mutate(picked.content, concepts, entities, isFixed);
    
    // Track full output
    _recentOutputs.push(result);
    if (_recentOutputs.length > RECENT_CAP) _recentOutputs.shift();
    
    // Track individual content words for per-word repetition penalty
    const contentWords = result.toLowerCase().replace(/[^a-z\s]/g, ' ').split(/\s+/)
        .filter(w => w.length > 3 && !FUNC.has(w));
    _recentWords.push(...contentWords);
    while (_recentWords.length > RECENT_WORD_CAP) _recentWords.shift();
    return result;
}

function _extractContentWords(text, limit = 8) {
    return (text || '')
        .toLowerCase()
        .replace(/[^a-z\s]/g, ' ')
        .split(/\s+/)
        .filter(Boolean)
        .filter(w => w.length > 2 && !FUNC.has(w) && !SKIP_WORDS.has(w))
        .slice(0, limit);
}

function _buildConceptPool(rawConcepts, extraTexts = [], entities = []) {
    const parsed = _parseConcepts(rawConcepts);
    const fromConcepts = parsed.map(c => ({ label: c.label, activation: c.activation }));
    const fromText = extraTexts
        .flatMap(text => _extractContentWords(text))
        .filter(Boolean)
        .map(label => ({ label, activation: 0.65 }));
    const fromEntities = entities
        .filter(Boolean)
        .map(label => String(label).toLowerCase())
        .filter(label => label.length > 2 && !FUNC.has(label))
        .map(label => ({ label, activation: 0.7 }));
    return [...fromConcepts, ...fromText, ...fromEntities];
}

function _isQuestionLike(text) {
    if (!text || typeof text !== 'string') return false;
    const trimmed = text.trim();
    const lower = trimmed.toLowerCase();
    if (trimmed.includes('?')) return true;
    return /^(who|what|where|when|why|how|is|are|do|does|did|can|could|would|should|will|shall)\b/.test(lower);
}

function _dequestionize(text) {
    if (!text || typeof text !== 'string') return null;
    const normalized = text.trim().replace(/\?+$/g, '').trim();
    return normalized && !_isQuestionLike(normalized) ? normalized : null;
}

function _matchesTopic(text, tokens) {
    if (!text || !Array.isArray(tokens) || tokens.length === 0) return false;
    const lower = text.toLowerCase();
    return tokens.some(token => token && lower.includes(token));
}

// ── Intent → utterance matching ─────────────────────────────────────────────
// Maps parsed intent to seed words that bias recall toward appropriate responses.
// This is not a template — it's a recall hint. The actual utterance comes from memory.
// Intent seeds match the slot-category entity tags written by languageBoot.
// Greeting uses only 'greeting' so it doesn't pull in the social group.
const INTENT_SEEDS = {
    greeting:     ['greeting'],
    farewell:     ['greeting'],
    wellbeing:    ['response', 'wellbeing', 'feel_state', 'be_state'],
    introspect:   ['response', 'introspect', 'think_about', 'notice_obj'],
    question:     ['answer', 'response', 'ask_topic', 'knowledge'],
    affirm:       ['social', 'response', 'knowledge', 'feel_state'],
    correct:      ['social', 'response', 'knowledge'],
    emotion:      ['response', 'statement', 'emotion_w', 'social'],
    teaching:     ['response', 'knowledge', 'introspect'],
    statement:    ['response', 'statement', 'introspect', 'emotion_w'],
    human_speech: ['human_speech', 'response'],
    response:     ['response', 'social'],
};

// ── respond ───────────────────────────────────────────────────────────────────
// RESPONSIVE: Every intent gets explicit acknowledgment. No memory-recall fallback.
// The system engages with what the human said, not just generates related utterances.
function _learnedReply(parsed, scState, entities, concepts, emotionContext, extraTexts = []) {
    const { cortex } = scState || {};
    const intentTag = parsed.intent === 'question' ? 'answer' : parsed.intent === 'statement' ? 'statement' : parsed.intent;
    const intentEntities = INTENT_SEEDS[parsed.intent] || [];
    const recallEntities = [...new Set([...entities, intentTag, ...intentEntities])];
    const utterances = cortex && typeof cortex.recall === 'function'
        ? _recallUtterances(cortex, recallEntities, emotionContext, 8, intentTag)
        : [];
    // Mutation can replace a single word with the requested topic, making an
    // unrelated sentence *look* relevant ("fear is danger" → "universe is
    // danger"). For questions, require topic evidence before any mutation.
    const groundedUtterances = parsed.intent === 'question'
        ? utterances.filter(utterance => _matchesTopic(utterance.content, entities))
        : utterances;
    if (groundedUtterances.length > 0) {
        const reply = _pickAndMutate(groundedUtterances, concepts, entities);
        if (reply && !(parsed.intent === 'question' && _isQuestionLike(reply))) return reply;
    }

    return null;
}

export function respond(parsed, scState) {
    const {
        neuralState, humanName, cortex, researchedFacts = null,
        conceptActivations: rawConcepts = null,
        focus = null,
        groundingMemories = [],
        internalThoughts = [],
        beliefs = [],
    } = scState || {};
    const { valence = 0 } = neuralState || {};
    const focusEntities = Array.isArray(focus?.entities) ? focus.entities : [];
    const mutationEntities = [...new Set([...(focusEntities || []), ...(parsed.entities || [])].filter(Boolean))];
    const emotionContext = valence > 0.3 ? 'happy' : valence < -0.3 ? 'upset' : parsed.emotion;
    const topic = parsed.topic || focus?.topic || mutationEntities[0] || null;

    // Quick: treat "no I asked a question" corrections as actual question requests
    if (parsed.intent === 'correct' && /asked a question/i.test((parsed.summary || '').toLowerCase())) {
        parsed.intent = 'question';
    }

    // ── LEARNING-GROUNDED REFLECTION ────────────────────────────────────
    // Recall memories and ground the reply in what the cortex has actually learned,
    // rather than hardcoding intent-specific phrases.
    const recentMemories = cortex && mutationEntities.length > 0
        ? cortex.recall(mutationEntities.slice(0, 3), emotionContext, 3, 'semantic')
        : [];
    const topicTokens = [...new Set([topic, ...(parsed.entities || [])]
        .filter(Boolean)
        .map(t => String(t).toLowerCase())
        .flatMap(t => t.split(/[^a-z]+/))
        .filter(Boolean))];
    const relevantThoughts = Array.isArray(internalThoughts) && internalThoughts.length > 0
        ? internalThoughts
            .filter(Boolean)
            .map(text => String(text).trim())
            .filter(text => {
                const lower = text.toLowerCase();
                const topicMentioned = topicTokens.some(token => lower.includes(token));
                const fearMentioned = /\b(fear|danger|pain|hurt|threat|unsafe|harm|attack|death|kill)\b/.test(lower);
                return topicMentioned && (!fearMentioned || topicTokens.some(token => /\b(fear|danger|pain|hurt|threat|unsafe|harm|attack|death|kill)\b/.test(token)));
            })
        : [];
    const internalDeliberation = relevantThoughts.length > 0 ? relevantThoughts.slice(-2).join(' ') : null;
    const safeInternalDeliberation = internalDeliberation && !_isQuestionLike(internalDeliberation) && _matchesTopic(internalDeliberation, topicTokens)
        ? internalDeliberation
        : null;
    const safeGroundingMemory = groundingMemories.find(m => m && m.content && !_isQuestionLike(m.content) && _matchesTopic(m.content, topicTokens));
    const safeResearchedFacts = researchedFacts && !_isQuestionLike(researchedFacts) && _matchesTopic(researchedFacts, topicTokens) ? researchedFacts : null;
    const bestBelief = Array.isArray(beliefs) ? beliefs[0] : null;

    const replyEntities = [...new Set([topic, ...(parsed.entities || []), ...mutationEntities].filter(Boolean))];
    const extraTexts = [internalDeliberation, groundingMemories[0]?.content, researchedFacts].filter(Boolean);
    const replyConcepts = _buildConceptPool(rawConcepts, extraTexts, replyEntities);

    const learnedReply = _learnedReply(parsed, scState, replyEntities, replyConcepts, emotionContext, extraTexts);
    // For questions: only use a learned reply if research hasn't produced a direct answer.
    // Also reject desire/want/miss patterns as answers to questions — they are
    // emotional reactions, not informational replies.
    const DESIRE_PATTERN = /^(i want|i need|i miss|i crave|i do not want|i wish|i long for|i prefer)\b/i;
    const researchHasAnswer = parsed.intent === 'question' && researchedFacts && researchedFacts.length > 10;
    if (learnedReply && !researchHasAnswer) {
        const isDesireReply = parsed.intent === 'question' && DESIRE_PATTERN.test(learnedReply.trim());
        const questionReplyValid = parsed.intent !== 'question' || _matchesTopic(learnedReply, topicTokens);
        if (questionReplyValid && !isDesireReply) return _result(learnedReply, parsed);
    }

    if (parsed.intent === 'question') {
        // Research answered the actual question — use it directly.
        // This is the primary answer path for questions; utterance recall
        // is a secondary path for when research hasn't run yet.
        if (researchedFacts && researchedFacts.length > 10) {
            const statement = _isQuestionLike(researchedFacts)
                ? _dequestionize(researchedFacts)
                : researchedFacts;
            if (statement) return _result(statement.slice(0, 280), parsed);
        }
        if (bestBelief?.verified) {
            return _result(bestBelief.claim.slice(0, 220), parsed);
        }
        if (safeGroundingMemory) {
            return _result(safeGroundingMemory.content.slice(0, 220), parsed);
        }
        if (safeInternalDeliberation) {
            return _result(safeInternalDeliberation.slice(0, 220), parsed);
        }
        if (groundingMemories[0]?.content) {
            const statement = _dequestionize(groundingMemories[0].content);
            if (statement) return _result(statement.slice(0, 220), parsed);
        }
        if (internalDeliberation) {
            const statement = _dequestionize(internalDeliberation);
            if (statement) return _result(statement.slice(0, 220), parsed);
        }
        // No research, no memories, no deliberation — acknowledge the question
        // rather than going silent. Silence is worse than honest uncertainty.
        if (topic) return _result(`I don't have enough grounding on ${topic} yet.`, parsed);
        return _result(`I'm not sure — I need more experience with that.`, parsed);
    }

    // Non-question intents: if learned reply failed, try grounding memories
    // and internal thoughts before going silent.
    if (safeGroundingMemory) return _result(safeGroundingMemory.content.slice(0, 220), parsed);
    if (safeInternalDeliberation) return _result(safeInternalDeliberation.slice(0, 220), parsed);
    if (recentMemories.length > 0) {
        const mem = recentMemories.find(m => !_isQuestionLike(m.content));
        if (mem) return _result(mem.content.slice(0, 220), parsed);
    }

    // Absolute floor — never go silent.
    const wm = scState?.workingMemory?.read?.(2) || [];
    const wmItem = wm.find(s => s.content && !_isQuestionLike(s.content) && s.source !== 'self_speech');
    if (wmItem) return _result(wmItem.content.slice(0, 180), parsed);

    return null;
}

// ── think ─────────────────────────────────────────────────────────────────────
export function think(scState) {
    const {
        neuralState, cortex, memories = [], workingMemory,
        activeGoal, conceptActivations: rawConcepts = null,
        loopBreak = null, deliberation = null, researchedFacts = null,
    } = scState;

    if (loopBreak) return loopBreak.text;

    if (activeGoal && deliberation?.concluded && deliberation.conclusion?.claim) {
        return deliberation.conclusion.claim.slice(0, 140);
    }

    const { valence = 0 } = neuralState || {};
    const emotionContext = valence > 0.3 ? 'happy' : valence < -0.3 ? 'upset' : 'neutral';
    const concepts = _parseConcepts(rawConcepts);
    const focusEntities = Array.isArray(scState?.focus?.entities) ? scState.focus.entities : [];
    const thinkEntities = [...new Set([
        ...(activeGoal ? [activeGoal.topic, ...(activeGoal.entities || [])] : []),
        ...focusEntities,
        ...concepts.slice(0, 3).map(c => c.label),
    ].filter(Boolean))];

    // ── Concept-net traversal (primary path when research is available) ────
    // Build a thought by finding which active concepts are grounded in the
    // research facts, then pulling the best matching semantic memory sentence.
    // This replaces random utterance mutation with actual content-driven thinking.
    if (researchedFacts && concepts.length > 0) {
        const anchor = activeGoal?.topic || thinkEntities[0];
        if (anchor) {
            const factWords = researchedFacts.toLowerCase()
                .replace(/[^a-z\s]/g, ' ').split(/\s+/)
                .filter(w => w.length > 4);
            const grounded = concepts
                .filter(c => factWords.some(w => w.includes(c.label) || c.label.includes(w)))
                .slice(0, 2);
            if (grounded.length >= 1) {
                const recallKeys = [anchor, ...grounded.map(c => c.label)];
                const anchorMem = cortex?.recall(recallKeys, emotionContext, 4, 'background')
                    .find(m => m.type === 'semantic' && m.content.length > 20);
                if (anchorMem) {
                    const sentence = anchorMem.content.split(/[.!]/)[0].trim();
                    if (sentence.length > 15) return sentence + '.';
                }
                // No matching memory yet — express the raw concept chain
                return `${anchor}: ${grounded.map(c => c.label).join(', ')}.`;
            }
        }
    }

    // ── Utterance recall fallback ─────────────────────────────────────────
    const utterances = _recallUtterances(cortex, thinkEntities, emotionContext, 12, 'introspect');
    if (utterances.length > 0) {
        const t = _pickAndMutate(utterances, concepts, thinkEntities);
        if (t) return t;
    }

    const wm = workingMemory ? workingMemory.read(2) : [];
    if (wm.length > 0) return wm[0].content.slice(0, 100);
    if (memories.length > 0) return memories[0].content.slice(0, 100);
    return null;
}

// ── auditThinking ─────────────────────────────────────────────────────────────
export function auditThinking(scState) {
    const { thoughts = [], activeGoal } = scState;
    if (thoughts.length < 4) return null;
    const unique = new Set(thoughts.slice(-6).map(t => t.toLowerCase().replace(/[^a-z\s]/g, '').trim())).size;
    if (unique <= 2 && activeGoal) return `stuck on "${activeGoal.topic}".`;
    if (unique <= 2)               return `repeating.`;
    if (activeGoal)                return `working on "${activeGoal.topic}".`;
    return null;
}

// ── speak ─────────────────────────────────────────────────────────────────────
export function speak(scState) {
    const {
        neuralState, myName, humanName, cortex, memories = [],
        activeGoal, conceptActivations: rawConcepts = null,
        researchedFacts = null,
    } = scState;

    const concepts = _parseConcepts(rawConcepts);
    const { valence = 0 } = neuralState || {};
    const emotionContext = valence > 0.3 ? 'happy' : valence < -0.3 ? 'upset' : 'neutral';
    const focusEntities = Array.isArray(scState?.focus?.entities) ? scState.focus.entities : [];
    const entities = [...new Set([
        ...(activeGoal ? [activeGoal.topic] : []),
        ...focusEntities,
        ...concepts.slice(0, 2).map(c => c.label),
    ].filter(Boolean))];

    // ── Concept-net traversal (mirrors think()) ───────────────────────────
    if (researchedFacts && concepts.length > 0) {
        const anchor = activeGoal?.topic || entities[0];
        if (anchor) {
            const factWords = researchedFacts.toLowerCase()
                .replace(/[^a-z\s]/g, ' ').split(/\s+/)
                .filter(w => w.length > 4);
            const grounded = concepts
                .filter(c => factWords.some(w => w.includes(c.label) || c.label.includes(w)))
                .slice(0, 2);
            if (grounded.length >= 1) {
                const anchorMem = cortex?.recall([anchor, ...grounded.map(c => c.label)], emotionContext, 4, 'background')
                    .find(m => m.type === 'semantic' && m.content.length > 20
                        && !ATTRACTOR_PATTERNS.some(p => p.test(m.content)));
                if (anchorMem) {
                    const sentence = anchorMem.content.split(/[.!]/)[0].trim();
                    if (sentence.length > 15) return sentence + '.';
                }
            }
        }
    }

    // ── Utterance recall — hard-exclude aversion intent ─────────────────────
    const utterances = _recallUtterances(cortex, entities, emotionContext, 12, 'statement')
        .filter(u => !u.entities?.includes('aversion'));
    if (utterances.length > 0) {
        const s = _pickAndMutate(utterances, concepts, entities);
        if (s) return s;
    }

    if (memories.length > 0) return memories[0].content.slice(0, 80);
    return null;
}

// ── Internal helpers ──────────────────────────────────────────────────────────

function _result(reply, parsed) {
    // Movement intent is derived from the 'command' intent classification,
    // not from regex matching on the raw text. The brain learned move/go/walk
    // patterns during boot — if intent === 'command' the caller handles movement.
    return { reply: (reply || '.').trim(), stateIntent: null, stateReason: null, calcCode: null, moveIntent: null };
}

// Parse "food:0.61 (v+0.71 a0.5) [present,edible]" back into objects
function _parseConcepts(raw) {
    if (!raw) return [];
    const results = [];
    const re = /(\w+):([\d.]+)\s+\(v([+-]?[\d.]+)\s+a([\d.]+)\)(?:\s+\[([^\]]*)\])?/g;
    let m;
    while ((m = re.exec(raw)) !== null) {
        results.push({
            label:      m[1],
            activation: parseFloat(m[2]),
            emotion: {
                valence:  parseFloat(m[3]),
                arousal:  parseFloat(m[4]),
                approach: parseFloat(m[3]) * 0.8,
            },
            topFeatures: m[5] ? m[5].split(',') : [],
        });
    }
    return results;
}
